import { createFileRoute } from "@tanstack/react-router";
import { PageHeader } from "@/components/shell/PageHeader";
import { CapabilityBadge, CapabilityCard } from "@/components/capability/CapabilityBadge";
import { useCapabilityReports } from "@/lib/capabilities/use-capabilities";
import { worstStatus } from "@/lib/capabilities/registry";
import { CAPABILITY_ORDER } from "@/lib/capabilities/types";

/**
 * OCADE Health: one page that answers "what can this actually do right now?".
 *
 * Every row is generated by the shared capability registry from observed
 * signals, so this page cannot disagree with the badge shown on the feature
 * itself. Nothing here is a mock: a capability with no probe result says it has
 * none, and each row carries the evidence its status was decided from.
 */
export const Route = createFileRoute("/_authenticated/ocade/health")({
  head: () => ({
    meta: [
      { title: "Health — OCADE" },
      {
        name: "description",
        content:
          "What OCADE can and cannot do on this device right now, with the evidence behind each status.",
      },
      { property: "og:title", content: "Health — OCADE" },
      {
        property: "og:description",
        content: "Live capability status for OCADE on this device.",
      },
      { name: "robots", content: "noindex" },
    ],
  }),
  component: HealthPage,
});

function HealthPage() {
  const reports = useCapabilityReports();
  const byId = new Map(reports.map((r) => [r.id, r]));
  const ordered = CAPABILITY_ORDER.map((id) => byId.get(id)).filter(
    (r): r is NonNullable<typeof r> => Boolean(r),
  );
  const overall = worstStatus(reports);

  return (
    <>
      <PageHeader
        eyebrow="OCADE"
        title="Health"
        description="Everything below is measured on this device, in this browser, right now. A capability that has not been verified says so rather than guessing."
        actions={<CapabilityBadge status={overall} />}
      />

      <div className="mt-6 grid gap-3 sm:grid-cols-2">
        {ordered.map((report) => (
          <CapabilityCard key={report.id} report={report} />
        ))}
      </div>

      <p className="mt-6 max-w-[70ch] text-xs leading-relaxed text-muted-foreground">
        Statuses are recalculated each time this page is opened. "Setup required" means the
        capability could work here once something is connected; "Not available here" means it cannot
        exist in this environment at all. Neither is a fault, and neither will be presented as
        working.
      </p>
    </>
  );
}
